import { Column, CreateDateColumn, Entity, PrimaryColumn } from "typeorm";
import type { PredictionDetail } from "@toolhackchain/shared";

// ID is generated by the application before batching, so no generated column here.
@Entity("predictions")
export class PredictionEntity {
  @PrimaryColumn({ name: "prediction_id", type: "uuid" }) predictionId!: string;
  @Column({ name: "stream_id", type: "uuid" }) streamId!: string;
  @Column({ name: "game_session_id", type: "uuid", unique: true }) gameSessionId!: string;
  // NULL khi AI không đưa ra dự đoán (reason ≠ OK); khi có thì B hoặc P (CHECK ở V9).
  @Column({ name: "predict_result", type: "varchar", length: 50, nullable: true }) predictResult!: string | null;
  @Column({ name: "confidence_score", type: "numeric", precision: 5, scale: 4, nullable: true }) confidenceScore!: string | null;
  @Column({ type: "jsonb" }) detail!: PredictionDetail;
  @Column({ name: "model_version", type: "text" }) modelVersion!: string;
  @Column({ type: "text" }) reason!: string;
  @CreateDateColumn({ name: "created_at", type: "timestamptz" }) createdAt!: Date;
}
